    enum EnumSynValue { A(SynA), I(SynI) }

    impl EnumSynValue {
        fn get_a(self) -> SynA {
            if let EnumSynValue::A(val) = self { val } else { panic!() }
        }
        fn get_i(self) -> SynI {
            if let EnumSynValue::I(val) = self { val } else { panic!() }
        }
    }

